int register_genl_family(struct genl_family *family) {
    int err;

    if (!family || !family->ops || !family->name)
        return -EINVAL;

    if (validate_ops(family->ops) < 0)
        return -EINVAL;

    mutex_lock(&genl_mutex);

    if (genl_family_find_by_name(family->name)) {
        mutex_unlock(&genl_mutex);
        return -EEXIST;
    }

    if (family->id == 0) {
        err = allocate_genl_id(family);
        if (err < 0) {
            mutex_unlock(&genl_mutex);
            return err;
        }
    } else if (family->id < GENL_ID_MIN || family->id >= GENL_ID_MAX) {
        mutex_unlock(&genl_mutex);
        return -ERANGE;
    }

    if (family->n_attrs > 0) {
        family->attrs = kmalloc(family->n_attrs * sizeof(void *), GFP_KERNEL);
        if (!family->attrs) {
            mutex_unlock(&genl_mutex);
            return -ENOMEM;
        }
        memset(family->attrs, 0, family->n_attrs * sizeof(void *));
    }

    err = validate_multicast_groups(family);
    if (err < 0) {
        kfree(family->attrs);
        mutex_unlock(&genl_mutex);
        return err;
    }

    list_add(&family->list, &genl_families);
    mutex_unlock(&genl_mutex);

    genl_notify_family_registered(family);
    genl_notify_multicast_groups(family);

    return 0;
}

int genl_register_family(struct genl_family *family) {
    int err = 0;

    if (!family)
        return -EINVAL;

    if (family->version == 0 || family->hdrsize > GENL_MAX_HDRSIZE ||
        family->name[GENL_NAMEMAX - 1] != '\0')
        return -EINVAL;

    if (family->parallel_ops && !family->netns_ops)
        return -EINVAL;

    write_lock(&genl_mutex);

    if (family->id) {
        if (genl_fam_offset(family->id))
            err = -EBUSY;
        else
            err = 0;
    } else {
        if (family->reserved != GENL_UNSPEC && family->reserved >= GENL_ID_RSV)
            family->id = family->reserved;
        else
            family->id = genl_get_id(family);
        if (family->id == 0)
            err = -EBUSY;
    }

    if (err)
        goto out;

    err = genl_register_ops(family);
    if (err)
        goto out;

    err = genl_validate_mcast_groups(family);
    if (err)
        goto out;

    list_add_tail(&family->entry, &genl_families);
    family->registered = true;

    out:
    write_unlock(&genl_mutex);

    if (err)
        genl_unregister_ops(family);

    return err;
}

int genl_register_family(struct genl_family *family) {
    int err;

    if (!family)
        return -EINVAL;

    if (family->version == 0)
        family->version = 1;

    if (family->name[GENL_NAMSIZ - 1]) {
        pr_err("genl: family name '%s' exceeds %d characters\n",
               family->name, GENL_NAMSIZ - 1);
        return -EINVAL;
    }

    if (family->id != GENL_ID_GENERATE && family->id >= GENL_ID_MAX)
        return -EINVAL;

    if (family->mcgrps) {
        struct genl_multicast_group *grp;
        int i;

        for (i = 0; i < family->n_mcgrps; i++) {
            grp = &family->mcgrps[i];
            if (!grp->name || grp->id >= GENL_MCAST_MAX_ID ||
                grp->id == 0) {
                pr_err("genl: invalid mcgrp %d for family '%s'\n", i,
                       family->name);
                return -EINVAL;
            }
        }
    }

    if (family->ops) {
        struct genl_ops *ops;
        int i;

        for (i = 0; i < family->n_ops; i++) {
            ops = &family->ops[i];
            if (!ops->cmd || ops->cmd > 255) {
                pr_err("genl: invalid command %d for family '%s'\n", i,
                       family->name);
                return -EINVAL;
            }
        }
    }

    down_write(&genl_mutex);

    if (family->id == GENL_ID_GENERATE) {
        int id;

        id = find_first_zero_bit(genl_fam_id_alloc, GENL_ID_MAX);
        if (id >= GENL_ID_MAX) {
            pr_err("genl: no free family ID\n");
            err = -ENOSPC;
            goto out;
        }

        family->id = id;
    }

    if (genl_families[family->id]) {
        pr_err("genl: family ID %d already in use\n", family->id);
        err = -EEXIST;
        goto out;
    }

    genl_families[family->id] = family;

    if (family->n_attrs) {
        family->attrbuf = kcalloc(family->n_attrs, sizeof(void *), GFP_KERNEL);
        if (!family->attrbuf) {
            err = -ENOMEM;
            goto out;
        }
    }

    if (family->ops) {
        int i;

        for (i = 0; i < family->n_ops; i++) {
            struct genl_ops *ops = &family->ops[i];

            if (ops->validate)
                ops->validate(family->id, ops->cmd, NULL);
        }
    }

    if (family->mcgrps) {
        int i;

        for (i = 0; i < family->n_mcgrps; i++) {
            struct genl_multicast_group *grp = &family->mcgrps[i];

            if (grp->id == 0) {
                int id;

                id = find_first_zero_bit(genl_mcast_id_alloc, GENL_MCAST_MAX_ID);
                if (id >= GENL_MCAST_MAX_ID) {
                    pr_err("genl: no free mcast id for family '%s', grp %s\n",
                           family->name, grp->name);
                    err = -ENOSPC;
                    goto out;
                }

                grp->id = id;
            }

            if (genl_mcast_groups[grp->id]) {
                pr_err("genl: mcast id %d for family '%s', grp %s already in use\n",
                       grp->id, family->name, grp->name);
                err = -EEXIST;
                goto out;
            }

            genl_mcast_groups[grp->id] = grp;
            genl_mcast_groups[grp->id]->name = kstrdup(grp->name, GFP_KERNEL);
            if (!genl_mcast_groups[grp->id]->name) {
                err = -ENOMEM;
                goto out;
            }
        }
    }

    list_add_tail(&family->list, &genl_families_list);
    err = 0;

out:
    up_write(&genl_mutex);
    return err;
}

int genl_register_family(struct genl_family *family)
{
    int err;

    if (!family)
        return -EINVAL;

    if (family->n_ops && !family->maxattr) {
        if (family->ops[0].maxattr) {
            family->maxattr = family->ops[0].maxattr;
        } else {
            family->maxattr = 1;
        }
    }

    down_write(&genl_mutex);

    if (genl_ctrl_find(family->name)) {
        err = -EEXIST;
        goto out;
    }

    if (family->id == GENL_ID_GENERATE) {
        int i;

        for (i = GENL_ID_MIN; i <= GENL_ID_MAX; i++) {
            if (!genl_families[i]) {
                family->id = i;
                break;
            }
        }

        if (i > GENL_ID_MAX) {
            err = -ENOMEM;
            goto out;
        }
    } else {
        if (family->id < GENL_ID_MIN || family->id > GENL_ID_MAX ||
            genl_families[family->id]) {
            err = -EINVAL;
            goto out;
        }
    }

    if (family->n_mcgrps > GENL_MCGRP_MAX) {
        err = -EINVAL;
        goto out;
    }

    family->header_size = 0;
    if (family->n_ops)
        family->header_size = max(family->ops[0].maxattr * NLA_ALIGN(sizeof(struct nlattr)), family->header_size);

    err = genl_register_ops(family);
    if (err < 0)
        goto out;

    genl_families[family->id] = family;

    genl_ctrl_event(CTRL_CMD_NEWFAMILY, family, NULL, 0);

    for (int i = 0; i < family->n_mcgrps; i++) {
        genl_ctrl_event(CTRL_CMD_NEWMCAST_GRP, family, &family->mcgrps[i], i);
    }

    out:
    up_write(&genl_mutex);
    return err;
}

int genl_register_family(struct genl_family *family)
{
    int err = 0;

    if (!family || !family->name || !family->version)
        return -EINVAL;

    if (family->maxattr) {
        if (!family->ops || !family->ops->policy) {
            pr_err("genl: family has attributes but no policy defined\n");
            return -EINVAL;
        }
    }

    mutex_lock(&genl_mutex);

    if (genl_family_find(family->name)) {
        pr_err("genl: family '%s' already registered\n", family->name);
        err = -EEXIST;
        goto unlock;
    }

    if (family->id >= GENL_ID_MIN) {
        if (family->id >= GENL_ID_MAX) {
            pr_err("genl: family id %u is out of range\n", family->id);
            err = -EINVAL;
            goto unlock;
        }

        if (genl_families[family->id]) {
            pr_err("genl: family id %u already in use\n", family->id);
            err = -EINVAL;
            goto unlock;
        }
    } else {
        int i;

        for (i = GENL_ID_MIN; i < GENL_ID_MAX; i++) {
            if (!genl_families[i]) {
                family->id = i;
                break;
            }
        }

        if (i == GENL_ID_MAX) {
            pr_err("genl: no free family id available\n");
            err = -ENOSPC;
            goto unlock;
        }
    }

    if (family->maxattr && family->ops) {
        family->ops->policy = kmemdup(family->ops->policy,
                                      sizeof(family->ops->policy[0]) * family->maxattr,
                                      GFP_KERNEL);
        if (!family->ops->policy) {
            pr_err("genl: failed to allocate memory for attribute policies\n");
            err = -ENOMEM;
            goto unlock;
        }
    }

    genl_families[family->id] = family;
    list_add(&family->list, &genl_families_list);

    pr_info("genl: registered family '%s' with id %u\n", family->name, family->id);

    genl_notify_family_registered(family);

unlock:
    mutex_unlock(&genl_mutex);
    return err;
}
